import {ToolRegistry} from './registry.js';

describe('tool input validation', () => {
  it('rejects missing required input specs/hal-engine-tool-input-validation/spec.md#1', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {name: 'forecast', description: 'Forecast', inputSchema: {type: 'object', required: ['location']}},
      async () => { calls++; return 'ok'; }
    );
    const response = await registry.execute('forecast', {});
    expect({result: response.result, calls}).toEqual({result: expect.stringMatching(/location.*required|required.*location/), calls: 0});
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.validation.test.ts"

